     1	import { OrderEventKind } from "../domain/order";
     2	
     3	const KIND_CODE: Record<OrderEventKind, string> = {
     4	  PAID: "paid",
     5	  SHIPPED: "ship",
     6	  DELIVERED: "dlvd",
     7	};
     8	
     9	/**
    10	 * 알림 메시지 키 — 사내 키 규약 `<네임스페이스>.<이벤트>.<업무 식별자>`.
    11	 * 소비 측은 이 키로 이미 처리한 메시지를 걸러낸다(재전달 대비).
    12	 */
    13	export function messageKey(namespace: string, kind: OrderEventKind, orderNo: string): string {
    14	  return `${namespace}.${KIND_CODE[kind]}.${orderNo}`;
    15	}
    16	
    17	export function kindFromCode(code: string): OrderEventKind | undefined {
    18	  return (Object.keys(KIND_CODE) as OrderEventKind[]).find((k) => KIND_CODE[k] === code);
    19	}
